module tb_TopModule;
  logic        clk;
  logic        areset;
  logic        predict_valid;
  logic        predict_taken;
  logic        train_mispredicted;
  logic        train_taken;
  logic [31:0] train_history;
  logic [31:0] predict_history;

  TopModule dut (
    .clk(clk),
    .areset(areset),
    .predict_valid(predict_valid),
    .predict_taken(predict_taken),
    .train_mispredicted(train_mispredicted),
    .train_taken(train_taken),
    .train_history(train_history),
    .predict_history(predict_history)
  );

  always #5 clk = ~clk;

  initial begin
    clk = 0;
    areset = 1;
    predict_valid = 0;
    predict_taken = 0;
    train_mispredicted = 0;
    train_taken = 0;
    train_history = 32'h0;

    #12;
    if (predict_history !== 32'h0) begin
      $display("SELFTEST FAIL: Reset failed, got %h", predict_history);
      $finish;
    end
    areset = 0;
    #10;

    // Test 1: Predict taken = 1
    @(posedge clk);
    predict_valid = 1;
    predict_taken = 1;
    @(posedge clk);
    predict_valid = 0;
    #1;
    if (predict_history !== 32'h1) begin
      $display("SELFTEST FAIL: Predict 1 failed, got %h", predict_history);
      $finish;
    end

    // Test 2: Predict taken = 0
    @(posedge clk);
    predict_valid = 1;
    predict_taken = 0;
    @(posedge clk);
    predict_valid = 0;
    #1;
    if (predict_history !== 32'h2) begin // 32'h1 shifted left with 0 -> 32'h2
      $display("SELFTEST FAIL: Predict 0 failed, got %h", predict_history);
      $finish;
    end

    // Test 3: Train mispredicted
    @(posedge clk);
    train_mispredicted = 1;
    train_taken = 1;
    train_history = 32'h12345678;
    @(posedge clk);
    train_mispredicted = 0;
    #1;
    // Expected: {train_history[30:0], train_taken} = {32'h12345678[30:0], 1'b1}
    // 32'h12345678 = 0001 0010 0013... bit 31 is 0. 
    // 32'h12345678[30:0] = 2345678. With 1 at LSB: {2345678, 1} -> wait, let's calculate exact expected value.
    // train_history = 32'h1234_5678;
    // train_history[30:0] = 32'h1234_5678 & 32'h7FFF_FFFF = 32'h1234_5678.
    // {32'h1234_5678, 1'b1} -> (32'h1234_5678 << 1) | 1 = 32'h2468_ACF1.
    if (predict_history !== 32'h2468ACF1) begin
      $display("SELFTEST FAIL: Misprediction load failed, got %h, expected %h", predict_history, 32'h2468ACF1);
      $finish;
    end

    // Test 4: Precedence (both predict_valid and train_mispredicted high)
    @(posedge clk);
    train_mispredicted = 1;
    train_taken = 0;
    train_history = 32'h0000_0001;
    predict_valid = 1;
    predict_taken = 1; // should be ignored due to misprediction precedence
    @(posedge clk);
    train_mispredicted = 0;
    predict_valid = 0;
    #1;
    // Expected: {32'h0000_0001[30:0], 1'b0} = 32'h0000_0002
    if (predict_history !== 32'h00000002) begin
      $display("SELFTEST FAIL: Precedence failed, got %h, expected 32'h00000002", predict_history);
      $finish;
    end

    $display("SELFTEST PASS");
    $finish;
  end
endmodule
